import {SKIRMISH_BIOMES,SKIRMISH_THREATS,SKIRMISH_DOCTRINES,DEFAULT_SKIRMISH,createSkirmish,decodeSkirmishDescriptor,validateSkirmishDescriptor,randomSkirmishSeed,skirmishElevation,CASTLE_PRACTICE_VERSION} from './skirmish-model.mjs';
import {BATTERY_BRIEF} from './objective-feedback.mjs';
import {resolveCastleConfig,DEFAULT_CASTLE_SELECTION} from './engine/castle-catalog.mjs';
import {COLLISION_REGIONS} from './engine/collision.mjs';
const html=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={grunt:'Foot soldiers',archer:'Archers',priest:'Healers',tallGrunt:'Heavy infantry',mount:'Horse riders',air:'Air fighters',trebuchet:'Trebuchets',fireDragon:'Fire dragon',iceDragon:'Ice dragon'};
const options=items=>Object.entries(items).map(([id,v])=>`<option value="${id}">${v.name}</option>`).join('');
export function skirmishPreviewSVG(scenario){
 const heights=scenario.encounter.heights,scale=.32,ground=x=>skirmishElevation(heights,x)*scale-115;
 const path=heights.map((y,i)=>`${i?'L':'M'}${i*20*scale},${(y*scale-115).toFixed(1)}`).join(' '),color=SKIRMISH_BIOMES[scenario.descriptor.biome].color;
 const keep=(x,friend)=>{const y=ground(x),top=y-52;
  if(scenario.castlePractice){
   const config=friend?scenario.castlePractice.friendly:scenario.castlePractice.enemy,[left,right,bodyTop,bottom]=COLLISION_REGIONS[config.regionKind].hitbox,station=y+config.shotOffset.y*scale;
   return `<g stroke="#17272b" stroke-width="2"><rect x="${(x+left)*scale}" y="${y+bodyTop*scale}" width="${(right-left)*scale}" height="${(bottom-bodyTop)*scale}" fill="${friend?'#d7c299':'#bd877b'}"/><path d="M${(x+left)*scale-2} ${station+3}H${(x+right)*scale+2}" stroke="${friend?'#aad5bb':'#db9988'}" stroke-width="5"/><circle cx="${x*scale}" cy="${station}" r="3" fill="#fff0bd"/><path d="M${x*scale} ${station-5}v-17h20l-6 7h-14" fill="${friend?'#aad5bb':'#db9988'}"/></g>`;
  }
  return `<g fill="${friend?'#d7c299':'#bd877b'}" stroke="#17272b" stroke-width="2"><path d="M${x*scale-18} ${y}v-52h10v8h16v-8h10v52Z"/><path d="M${x*scale-4} ${y}v-15h9v15" fill="#17272b"/><path d="M${x*scale} ${top-2}v-17"/><path d="M${x*scale} ${top-19}h22l-6 7h-16Z" fill="${friend?'#aad5bb':'#db9988'}"/></g>`;};
 return `<svg viewBox="0 0 640 210" role="img" aria-label="Preview of ${html(scenario.name)}: home keep on the left, enemy keep on the right, ${scenario.encounter.towers.length} forward towers.${scenario.castlePractice?' Both Highwatch keeps show their actual taller collision body and firing station.':''} Terrain comes from this exact seed."><defs><linearGradient id="skirmishSky" x2="0" y2="1"><stop stop-color="#122c36"/><stop offset="1" stop-color="#4a6970"/></linearGradient></defs><rect width="640" height="210" rx="14" fill="url(#skirmishSky)"/><circle cx="510" cy="31" r="16" fill="#e6cf9c" opacity=".7"/><path d="${path}L640 210H0Z" fill="${color}" fill-opacity=".3"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3"/>${scenario.encounter.towers.map(x=>`<path d="M${x*scale-9} ${ground(x)}v-35h5v5h8v-5h5v35" fill="#b9b3a0" stroke="#24353a" stroke-width="2"/>`).join('')}${keep(350,true)}${keep(1800,false)}<text x="32" y="190" fill="#d5e9e5" font-size="11" font-family="sans-serif">HOME KEEP</text><text x="540" y="190" fill="#f3d6c5" font-size="11" font-family="sans-serif">ENEMY KEEP</text></svg>`;
}
export function skirmishBriefHTML(scenario){
 const {descriptor:d,encounter:e,kit}=scenario,tier=SKIRMISH_THREATS[d.threat],biome=SKIRMISH_BIOMES[d.biome],doctrine=SKIRMISH_DOCTRINES[d.doctrine];
 const comparison=scenario.castlePractice,classic=comparison?resolveCastleConfig(DEFAULT_CASTLE_SELECTION,{team:'good',baseHp:comparison.friendly.baseHp}):null;
 const castleBrief=comparison?`<div class="skirmish-objective"><strong>Supplied castle comparison · level 1 only</strong><p>Both sides start with Highwatch Keep. Your keep: ${comparison.friendly.hp.toLocaleString()} HP; enemy keep: ${comparison.enemy.hp.toLocaleString()} HP (80% of ${e.enemyKeepHP.toLocaleString()} pre-type HP). Both have a firing station 250 world units above their ground, 50 above Classic, and 2 total shelter berths. Your hero uses one berth.</p><p>Classic Keep is also supplied for this attempt: ${classic.hp.toLocaleString()} home HP, a 200-unit station and 4 berths. Choose it in Build before Start to compare on this same seed. Higher shots can clear some terrain; the taller masonry is also exposed to damage. Resistance, ordinary troop costs and controls are unchanged. No castle upgrades.</p><p>${comparison.predeployedArchers} enemy archers from the listed finite company begin sheltered in their keep; they are not extra enemies. Their ordinary AI may leave when no target is in range; at this starting distance they normally leave immediately to advance. Later shelter use needs a nearby reachable target. Neither height nor an empty berth guarantees an archer will stay or hit.</p></div>`:'';
 const objective=comparison?'<strong>Hold your keep, break theirs, clear the field</strong><p>Destroy the enemy keep, clear all deployed enemies and return your home flag to its base. Breaking the enemy keep withdraws its undeployed reserves. Enemy flag capture alone cannot win. Losing your hero, home flag or home keep defeats this attempt. Ordinary archers, infantry, riders and siege can counter either castle.</p>':d.doctrine==='levy'?`<strong>Hold your keep, break theirs, clear the field</strong><p>Open Army → Muster to call one of four finite five-unit levy waves. Each contains 3 foot soldiers, 1 archer and 1 healer at rank 2. Ten temporary slots are separate from paid troops. There is no Auto levy call, gold cost, reserve charge or permanent contract.</p><p>Counterattacks start at ${scenario.levyStages.map(stage=>`${stage.second}s: ${stage.label} (${stage.types.length})`).join('; ')}. Full enemy slots can delay entry. The existing wave indicator counts down the next stage.</p><p>Destroying the enemy keep withdraws all its undeployed reserves, including future stages. Clear deployed enemies and recover your home flag to win. Enemy flag capture alone cannot win. Losing your hero, home flag or home keep is defeat. Time alone never wins.</p>`:e.objective==='intercept-battery'?`<strong>${BATTERY_BRIEF.title}</strong><p>${BATTERY_BRIEF.goal}</p><p>${BATTERY_BRIEF.counterplay}</p><p>${BATTERY_BRIEF.opening}</p>`:'<strong>Win the field</strong><p>Return their flag while yours is safe, or defeat the remaining army. Destroying the enemy keep cuts off its undeployed reserves. Protect your hero and home flag.</p>';
 return `<div class="skirmish-preview">${skirmishPreviewSVG(scenario)}</div><div class="skirmish-field-heading"><div><span class="skirmish-kicker">${biome.name} · ${html(e.timeOfDay)}</span><h3>${html(scenario.name)}</h3></div><span class="skirmish-threat">${tier.difficulty[0].toUpperCase()+tier.difficulty.slice(1)} combat</span></div><p class="skirmish-description">${biome.description} ${doctrine.description}</p><dl class="skirmish-facts"><div><dt>Finite company</dt><dd>${e.roster.length} enemies</dd></div><div><dt>Forward towers</dt><dd>${e.towers.length}</dd></div><div><dt>Enemy keep</dt><dd>${(comparison?comparison.enemy.hp:e.enemyKeepHP).toLocaleString()} HP${comparison?' · Highwatch':''}</dd></div></dl><ul class="skirmish-company">${Object.entries(scenario.counts).map(([type,n])=>`<li><b>${n}</b> ${names[type]}</li>`).join('')}</ul><div class="skirmish-objective">${objective}</div>${castleBrief}<details class="skirmish-kit"><summary>Supplied practice kit · rank ${kit.rank} · ${kit.gold.toLocaleString()} gold</summary><p>Basic Arrow rank ${kit.basicRank}; Fire, Ice, Bomb and Flak arrows plus five army cards at rank ${kit.skillRank}. ${kit.reserve} reserve recruits. Automatic recruitment starts off. Summon from your cards or turn it on in Army. Ordinary costs, damage and cooldowns apply.</p><p>Every retry resets to these supplies.${comparison?' Classic and Highwatch are supplied practice cards only; Highwatch is selected again on retry. They cannot be exported as campaign ownership. No gold is spent to supply these two cards.':''} Gold, XP and victories earned here stay in this practice attempt. No campaign progress or save is changed. Saved decks also belong only to this attempt. Export their deck codes before a fresh retry, restart or new field.</p></details><p class="skirmish-validation">Use full-power Auto aim for distant shots and lead moving targets. A seed recreates the starting field; your actions shape the battle.</p>`;
}
/** Shared workshop controller for the battle panel and standalone launch page.
 * Editing is a draft. Only Prepare calls onPrepare, and only after validation.
 */
export function createSkirmishWorkshop({host,getDescriptor=()=>DEFAULT_SKIRMISH,onPrepare=()=>{},onClose=()=>{},seedFactory=randomSkirmishSeed}={}){
 let current=null,revision=0;
 host.innerHTML=`<div class="skirmish-workspace"><aside class="skirmish-controls"><div><span class="skirmish-kicker">REPLAYABLE PRACTICE</span><h3>Make your next field.</h3><p>Pick a company, shape the land, then defend your banner.</p></div><label for="skirmishSeed">World seed<input id="skirmishSeed" inputmode="numeric" maxlength="10" autocomplete="off" spellcheck="false"></label><button id="skirmishNewSeed" class="skirmish-secondary" type="button">Roll a new seed</button><label for="skirmishBiome">Landscape<select id="skirmishBiome">${options(SKIRMISH_BIOMES)}</select></label><label for="skirmishThreat">Company strength<select id="skirmishThreat">${options(SKIRMISH_THREATS)}</select></label><label for="skirmishDoctrine">Enemy doctrine<select id="skirmishDoctrine">${options(SKIRMISH_DOCTRINES)}</select></label><p id="skirmishThreatNote"></p><div class="skirmish-code"><label for="skirmishCode">Copy or paste a seed code<input id="skirmishCode" maxlength="100" autocomplete="off" spellcheck="false"></label><div><button id="skirmishCopy" type="button">Copy seed</button><button id="skirmishLoadCode" type="button">Use code</button></div></div></aside><section class="skirmish-brief" aria-label="Generated field preview"><div id="skirmishPreview"></div><p id="skirmishStatus" role="status" aria-live="polite"></p><div class="skirmish-actions"><button id="skirmishPrepare" type="button">Prepare this field</button><button id="skirmishCancel" class="skirmish-secondary" type="button">Back to lobby</button></div><p class="skirmish-safety">Separate assisted practice. Campaign saves and earned banners stay untouched. Export any saved deck codes before preparing a fresh field; each attempt starts with an empty deck library.</p></section></div>`;
 const $=id=>host.querySelector('#'+id),status=text=>{$('skirmishStatus').textContent=text;};
 function fill(d){$('skirmishSeed').value=String(d.seed);$('skirmishBiome').value=d.biome;$('skirmishThreat').value=d.threat;$('skirmishDoctrine').value=d.doctrine;}
 function read(){const text=$('skirmishSeed').value.trim();if(!/^[1-9][0-9]{0,9}$/.test(text))throw new TypeError('Enter a whole-number seed from 1 to 4294967295.');return validateSkirmishDescriptor({version:$('skirmishDoctrine').value==='highwatch'?CASTLE_PRACTICE_VERSION:1,seed:Number(text),biome:$('skirmishBiome').value,threat:$('skirmishThreat').value,doctrine:$('skirmishDoctrine').value});}
 function preview(){revision++;try{current=createSkirmish(read());$('skirmishPreview').innerHTML=skirmishBriefHTML(current);$('skirmishCode').value=current.code;$('skirmishPrepare').disabled=false;$('skirmishCopy').disabled=false;$('skirmishThreatNote').textContent=SKIRMISH_THREATS[current.descriptor.threat].description;status('Preview ready. Preparing waits in the lobby for Start.');return true;}catch(error){current=null;$('skirmishPrepare').disabled=true;$('skirmishCopy').disabled=true;status(error.message);return false;}}
 function open(){fill(getDescriptor());preview();}
 for(const id of ['skirmishSeed','skirmishBiome','skirmishThreat','skirmishDoctrine'])$(id).addEventListener('change',preview);
 $('skirmishNewSeed').onclick=()=>{try{$('skirmishSeed').value=String(seedFactory());preview();}catch{status('A new seed could not be made. Enter a number instead.');}};
 $('skirmishLoadCode').onclick=()=>{revision++;try{const descriptor=decodeSkirmishDescriptor($('skirmishCode').value);fill(descriptor);preview();status('Seed code loaded. Review the field, then prepare it.');}catch(error){current=null;$('skirmishPrepare').disabled=true;$('skirmishCopy').disabled=true;status(error.message);}};
 $('skirmishCopy').onclick=async()=>{if(!preview())return;const code=current.code,copyRevision=revision;$('skirmishCode').focus?.();$('skirmishCode').select?.();try{if(!globalThis.navigator?.clipboard?.writeText)throw new Error('Clipboard unavailable');await globalThis.navigator.clipboard.writeText(code);if(revision!==copyRevision)return;status('Seed code copied. It recreates this starting field and supplied kit.');}catch{if(revision!==copyRevision)return;status('Seed code selected. Copy it manually to keep this field.');}};
 $('skirmishPrepare').onclick=()=>{if(preview())onPrepare(current.descriptor);};
 for(const id of ['skirmishSeed','skirmishCode'])$(id).addEventListener('input',()=>{revision++;});
 $('skirmishCancel').onclick=()=>{revision++;onClose();};
 return {open,invalidate(){revision++;},get scenario(){return current;}};
}
